function(container, apiUrl, tables) {
  let currentRecordId = null;
  let workRecords = [];
  let workItems = [];

  // 時間計算関数
  function calculateDuration(startTime, endTime) {
    if (!startTime || !endTime) return '';
    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);
    if (end <= start) return '';
    const diffMs = end - start;
    const hours = Math.floor(diffMs / (1000 * 60 * 60));
    const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
    return `${hours}時間${minutes}分`;
  }

  function calculateMinutes(startTime, endTime) {
    if (!startTime || !endTime) return 0;
    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);
    if (end <= start) return 0;
    return Math.floor((end - start) / (1000 * 60));
  }

  // 異常値チェック
  function checkAnomalies(workMinutes, breakMinutes) {
    const warnings = [];
    const netMinutes = workMinutes - (breakMinutes || 0);

    if (workMinutes > 12 * 60) { // 12時間超過
      warnings.push('作業時間が12時間を超えています');
    }
    if (netMinutes > 10 * 60) { // 正味10時間超過
      warnings.push('正味作業時間が10時間を超えています');
    }
    if (breakMinutes > workMinutes * 0.5) { // 中断時間が作業時間の50%超過
      warnings.push('中断時間が作業時間の50%を超えています');
    }

    const warningArea = container.querySelector('#warning-area');
    const warningMessage = container.querySelector('#warning-message');

    if (warnings.length > 0) {
      warningMessage.textContent = warnings.join('、');
      warningArea.style.display = 'block';
    } else {
      warningArea.style.display = 'none';
    }
  }

  // 時間変更時の自動計算
  function updateTimeCalculation() {
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;

    const workDuration = calculateDuration(startTime, endTime);
    const workMinutes = calculateMinutes(startTime, endTime);
    const netMinutes = workMinutes - breakTime;

    container.querySelector('#display-work-duration').value = workDuration;

    if (netMinutes >= 0) {
      const netHours = Math.floor(netMinutes / 60);
      const netMins = netMinutes % 60;
      container.querySelector('#display-net-duration').value = `${netHours}時間${netMins}分`;
    } else {
      container.querySelector('#display-net-duration').value = '計算エラー';
    }

    checkAnomalies(workMinutes, breakTime);
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 作業記録一覧を取得
      workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];

      // 作業項目マスタを取得
      workItems = await window.aivicApi.list(3) || tables[3]?.records || [];

      // 修正対象作業記録のドロップダウンを更新
      const selectWorkRecord = container.querySelector('#select-work-record');
      selectWorkRecord.innerHTML = '<option value="">選択してください</option>' +
        workRecords.filter(r => r.承認状態 !== '承認済み').map(record => 
          `<option value="${record.作業記録ID}">${record.作業日?.split('T')[0] || ''} - ${record.プロジェクト名 || ''} (${record.作業種別 || ''})</option>`
        ).join('');

      // 作業項目ドロップダウンを更新
      const selectWorkItem = container.querySelector('#select-work-item');
      selectWorkItem.innerHTML = '<option value="">選択してください</option>' +
        workItems.filter(item => item.有効フラグ).map(item => 
          `<option value="${item.作業項目ID}">${item.作業項目名}</option>`
        ).join('');

    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 作業記録選択時の処理
  container.querySelector('#select-work-record').addEventListener('change', function() {
    const recordId = this.value;
    currentRecordId = recordId;

    if (!recordId) {
      // フォームクリア
      container.querySelector('#input-work-date').value = '';
      container.querySelector('#input-start-time').value = '';
      container.querySelector('#input-end-time').value = '';
      container.querySelector('#input-break-time').value = '';
      container.querySelector('#input-work-detail').value = '';
      container.querySelector('#input-correction-reason').value = '';
      container.querySelector('#select-work-item').value = '';
      container.querySelector('#display-work-duration').value = '';
      container.querySelector('#display-net-duration').value = '';
      container.querySelector('#warning-area').style.display = 'none';
      return;
    }

    const record = workRecords.find(r => r.作業記録ID === recordId);
    if (record) {
      // フォームに既存データを設定
      const workDate = record.作業日 ? new Date(record.作業日).toISOString().split('T')[0] : '';
      const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toTimeString().slice(0, 5) : '';
      const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toTimeString().slice(0, 5) : '';

      container.querySelector('#input-work-date').value = workDate;
      container.querySelector('#input-start-time').value = startTime;
      container.querySelector('#input-end-time').value = endTime;
      container.querySelector('#input-break-time').value = '0';
      container.querySelector('#input-work-detail').value = record.作業内容 || '';
      container.querySelector('#select-work-item').value = record.作業種別 || '';

      updateTimeCalculation();
    }
  });

  // 元データ参照ボタン
  container.querySelector('#btn-load-record').addEventListener('click', function() {
    if (!currentRecordId) {
      alert('修正対象の作業記録を選択してください');
      return;
    }

    const record = workRecords.find(r => r.作業記録ID === currentRecordId);
    if (record) {
      const details = [
        `作業日: ${record.作業日?.split('T')[0] || ''}`,
        `プロジェクト: ${record.プロジェクト名 || ''}`,
        `作業場所: ${record.作業場所 || ''}`,
        `作業種別: ${record.作業種別 || ''}`,
        `進捗状況: ${record.進捗状況 || ''}`,
        `承認状態: ${record.承認状態 || ''}`,
        `作業内容: ${record.作業内容 || ''}`
      ].join('\n');

      alert(`元データ詳細:\n\n${details}`);
    }
  });

  // 時間入力の変更監視
  container.querySelector('#input-start-time').addEventListener('change', updateTimeCalculation);
  container.querySelector('#input-end-time').addEventListener('change', updateTimeCalculation);
  container.querySelector('#input-break-time').addEventListener('input', updateTimeCalculation);

  // 修正完了ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    if (!currentRecordId) {
      alert('修正対象の作業記録を選択してください');
      return;
    }

    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;
    const workDetail = container.querySelector('#input-work-detail').value.trim();
    const correctionReason = container.querySelector('#input-correction-reason').value.trim();
    const workItemId = container.querySelector('#select-work-item').value;

    if (!startTime || !endTime) {
      alert('開始時刻と終了時刻を入力してください');
      return;
    }

    if (!correctionReason) {
      alert('修正理由を入力してください');
      return;
    }

    if (!workDetail) {
      alert('作業内容詳細を入力してください');
      return;
    }

    const workMinutes = calculateMinutes(startTime, endTime);
    if (workMinutes <= 0) {
      alert('終了時刻は開始時刻より後に設定してください');
      return;
    }

    try {
      // 作業記録を更新
      const workDate = container.querySelector('#input-work-date').value;
      const startDateTime = new Date(`${workDate}T${startTime}`).toISOString();
      const endDateTime = new Date(`${workDate}T${endTime}`).toISOString();

      const updateData = {
        作業開始時刻: startDateTime,
        作業終了時刻: endDateTime,
        作業時間: workMinutes - breakTime,
        作業内容: workDetail,
        承認状態: '未承認',
        更新日時: new Date().toISOString()
      };

      const updated = await window.aivicApi.update(1, currentRecordId, updateData);

      if (updated) {
        // 異常値検出ログを記録（警告が表示されている場合）
        const warningArea = container.querySelector('#warning-area');
        if (warningArea.style.display !== 'none') {
          const warningMessage = container.querySelector('#warning-message').textContent;
          await window.aivicApi.save(4, {
            異常値検出ログID: crypto.randomUUID(),
            検出対象テーブル: '作業記録',
            検出対象レコードID: currentRecordId,
            ユーザーID: 'current-user', // 実際の実装では現在のユーザーIDを使用
            異常値種別: '工数修正時異常値',
            検出項目: '作業時間',
            検出値: `${Math.floor(workMinutes/60)}時間${workMinutes%60}分`,
            閾値: '12時間',
            重要度: '中',
            確認状況: '未確認',
            通知送信フラグ: false,
            対応メモ: `修正理由: ${correctionReason}`,
            検出日時: new Date().toISOString(),
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString()
          });
        }

        alert('工数修正が完了しました');
        window.showScreen("scr-1778907367889");
      } else {
        alert('修正に失敗しました');
      }
    } catch (error) {
      console.error('修正エラー:', error);
      alert('修正中にエラーが発生しました');
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    if (confirm('修正内容を破棄して戻りますか？')) {
      window.showScreen("scr-1778907367889");
    }
  });

  // 初期データ読み込み実行
  loadInitialData();
}
